import { Component } from '@angular/core';
import { IonicPage, NavController, NavParams } from 'ionic-angular';

import { Impostazione } from "../../models/impostazione";
import { ImpostazioneProvider } from "../../providers/impostazione/impostazione";

@IonicPage()
@Component({
  selector: 'page-impostazioni-detail',
  templateUrl: 'impostazioni-detail.html'
})
export class ImpostazioniDetailPage {
  item: any;

  defaultImpostazione: any = {
		"comune"          	:		"0",
    "cod_istat"         :   "",
		"zona"       		    :		"0",
		"attiva_notifiche"  :		0,
		"data_ora"	      	:		null,
		};

  constructor(public navCtrl: NavController, navParams: NavParams, items: ImpostazioneProvider) {
    this.item = navParams.get('item') || this.defaultImpostazione;
  }

}



